(() => {
  let lang='en';try{lang=localStorage.getItem('gbtor365-language')==='es'?'es':'en';}catch{}
  const copy={en:{headline:'Your accounting,<br>in sync.',intro:'A clear path from GlobalBake to Restaurant365.',workspace:'FINANCE WORKSPACE',welcome:'Welcome back.',description:'Sign in to your Artimex workspace.',email:'Email address',password:'Password',show:'Show',hide:'Hide',submit:'Sign in',busy:'Signing in…',help:'Access is reserved for authorized Artimex users. Contact your administrator if you need access.',note:'Private accounting workspace · GlobalBake → Restaurant365.',credentials:'Email or password incorrect.',rate_limit:'Too many attempts. Please try again in 15 minutes.',unavailable:'Sign-in is temporarily unavailable. Please contact your administrator.',network:'Unable to reach the server. Please try again.'},es:{headline:'Tu contabilidad,<br>conectada.',intro:'Un camino claro de GlobalBake a Restaurant365.',workspace:'ESPACIO CONTABLE',welcome:'Bienvenido de nuevo.',description:'Inicia sesión en tu espacio Artimex.',email:'Correo electrónico',password:'Contraseña',show:'Mostrar',hide:'Ocultar',submit:'Iniciar sesión',busy:'Iniciando sesión…',help:'Acceso reservado para usuarios autorizados de Artimex. Contacta a tu administrador si necesitas acceso.',note:'Espacio contable privado · GlobalBake → Restaurant365.',credentials:'Correo o contraseña incorrectos.',rate_limit:'Demasiados intentos. Inténtalo de nuevo en 15 minutos.',unavailable:'Inicio de sesión no disponible. Contacta a tu administrador.',network:'No se pudo conectar al servidor. Inténtalo de nuevo.'}};
  const el=id=>document.getElementById(id);let error='',busy=false;
  function render(){document.documentElement.lang=lang;document.querySelectorAll('[data-text]').forEach(node=>{const key=node.dataset.text;if(key==='headline')node.innerHTML=copy[lang][key];else node.textContent=copy[lang][key];});el('show-password').textContent=copy[lang][el('password').type==='password'?'show':'hide'];el('show-password').setAttribute('aria-label',el('show-password').textContent);el('language').setAttribute('aria-label',lang==='en'?'Switch to Spanish':'Cambiar a inglés');el('sign-in').textContent=copy[lang][busy?'busy':'submit'];el('login-error').textContent=copy[lang][error]||'';el('login-error').classList.toggle('hide',!error);}
  el('language').addEventListener('click',()=>{lang=lang==='en'?'es':'en';try{localStorage.setItem('gbtor365-language',lang);}catch{}render();});
  el('show-password').addEventListener('click',()=>{const show=el('password').type==='password';el('password').type=show?'text':'password';el('show-password').setAttribute('aria-pressed',String(show));render();});
  el('login-form').addEventListener('submit',async event=>{
    event.preventDefault();if(busy)return;busy=true;error='';el('sign-in').disabled=true;render();
    try{const response=await fetch('/api/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:el('email').value,password:el('password').value})});
      if(response.ok){el('password').value='';location.replace('/'+location.hash);return;}
      error=response.status===401?'credentials':response.status===429?'rate_limit':'unavailable';el('password').value='';el('password').focus();
    }catch{error='network';}finally{busy=false;el('sign-in').disabled=false;render();}
  });
  render();
})();
